def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_o = opp[-1]
    last_m = me[-1]

    # Detect defector by frequency after enough rounds.
    if n >= 8:
        defs = sum(1 for x in opp if x == 'D')
        if defs >= n - 1:
            return 'D'
        if n >= 20 and defs >= int(0.85 * n):
            return 'D'

    # Forgiveness / reset if opponent has just cooperated after a bad stretch.
    if n >= 3 and opp[-1] == 'C' and opp[-2] == 'C':
        return 'C'

    # Tit-for-tat-like core but with occasional stochastic probing limited.
    if n < 4:
        if last_o == 'D':
            return 'D' if n >= 2 else 'C'
        return 'C'

    # Cooperative phase: maintain cooperation unless recent pattern suggests exploitation.
    recent = opp[-5:] if n >= 5 else opp
    recent_defs = sum(1 for x in recent if x == 'D')
    # If few recent D, cooperate to build payoff.
    if recent_defs <= 1:
        return 'C'

    # If opponent has been defecting often, retaliate but test forgiveness occasionally.
    if recent_defs >= 3:
        # small random chance to offer cooperation to restart mutual cooperation
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Mixed case: mirror last opponent action with slight bias to cooperation.
    if last_o == 'D':
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    return 'C'
